    @Override
    public void start() {
        if (!this.popConsumerStore.start()) {
            throw new RuntimeException("PopConsumerStore init error");
        }
        if (this.popConsumerCache != null) {
            this.popConsumerCache.start();
        }
        super.start();
    }

    @Override
    public void shutdown() {
        // Block shutdown thread until write records finish
        super.shutdown();
        do {
            this.waitForRunning(10);
        }
        while (consumerRunning.get());
        if (this.popConsumerCache != null) {
            this.popConsumerCache.shutdown();
        }
        if (this.popConsumerStore != null) {
            this.popConsumerStore.shutdown();
        }
    }

    @Override
    public void run() {
        this.consumerRunning.set(true);
        while (!isStopped()) {
            try {
                // to prevent concurrency issues during read and write operations
                long reviveCount = this.revive(System.currentTimeMillis() - 50L,
                    brokerConfig.getPopReviveMaxReturnSizePerRead());

                long current = System.currentTimeMillis();
                if (lastCleanupLockTime.get() + TimeUnit.MINUTES.toMillis(1) < current) {
                    this.consumerLockService.removeTimeout();
                    this.lastCleanupLockTime.set(current);
                }

                if (reviveCount == 0) {
                    this.waitForRunning(500);
                }
            } catch (Exception e) {
                log.error("PopConsumerService revive error", e);
            }
        }
        this.consumerRunning.set(false);
    }
}

public interface PopConsumerKVStore {

    /**
     * Starts the storage service.
     */
    boolean start();

    /**
     * Shutdown the storage service.
     */
    boolean shutdown();

    /**
     * Gets the file path of the storage.
     * @return The file path of the storage.
     */
    String getFilePath();

    /**
     * Writes a list of consumer records to the storage.
     * @param consumerRecordList The list of consumer records to be written.
     */
    void writeRecords(List<PopConsumerRecord> consumerRecordList);

    /**
     * Deletes a list of consumer records from the storage.
     * @param consumerRecordList The list of consumer records to be deleted.
     */
    void deleteRecords(List<PopConsumerRecord> consumerRecordList);

    /**
     * Scans and returns a list of expired consumer records before the current time.
     * @param currentTime The current revive checkpoint timestamp.
     * @param maxCount The maximum number of records to return.
     * @return A list of expired consumer records.
     */
    List<PopConsumerRecord> scanExpiredRecords(long currentTime, int maxCount);
}

